mapper.select:
SELECT

,g.gonggao_name as gonggaoName
,COALESCE(
    a.pinglunren_name,
    CASE
        WHEN a.pinglunren_table = 'xuesheng' THEN xuesheng.xuesheng_name
        WHEN a.pinglunren_table = 'laoshi' THEN laoshi.laoshi_name
        WHEN a.pinglunren_table = 'qiye' THEN qiye.qiye_name
        WHEN a.pinglunren_table = 'users' THEN users.username
        ELSE ''
    END
) as pinglunrenName
FROM gonggao_comment a
LEFT JOIN gonggao g ON a.gonggao_id = g.id
LEFT JOIN xuesheng xuesheng ON a.pinglunren_table = 'xuesheng' AND a.pinglunren_id = xuesheng.id
LEFT JOIN laoshi laoshi ON a.pinglunren_table = 'laoshi' AND a.pinglunren_id = laoshi.id
LEFT JOIN qiye qiye ON a.pinglunren_table = 'qiye' AND a.pinglunren_id = qiye.id
LEFT JOIN users users ON a.pinglunren_table = 'users' AND a.pinglunren_id = users.id



        and a.id in

            #{item}



        and a.gonggao_id = #{params.gonggaoId}


        and g.fabuzhe_id = #{params.gonggaoFabuzheId}


        and g.fabuzhe_role = #{params.gonggaoFabuzheRole}


        and a.pinglunren_id = #{params.pinglunrenId}


        and (
            a.pinglunren_id != #{params.excludePinglunrenId}
            or a.pinglunren_role != #{params.excludePinglunrenRole}
        )


        and a.pinglunren_role = #{params.pinglunrenRole}


        and a.pinglunren_table = #{params.pinglunrenTable}


        and (
            a.pinglunren_name like CONCAT('%',#{params.pinglunrenName},'%')
            or xuesheng.xuesheng_name like CONCAT('%',#{params.pinglunrenName},'%')
            or laoshi.laoshi_name like CONCAT('%',#{params.pinglunrenName},'%')
            or qiye.qiye_name like CONCAT('%',#{params.pinglunrenName},'%')
            or users.username like CONCAT('%',#{params.pinglunrenName},'%')
        )


        and g.gonggao_name like CONCAT('%',#{params.gonggaoName},'%')


        and a.gonggao_comment_content like CONCAT('%',#{params.gonggaoCommentContent},'%')



order by a.${params.orderBy} desc
